import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.yZB1U4Nl.js";const p=JSON.parse('{"title":"Interface: Client","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"api/host/interfaces/Client.md","filePath":"api/host/interfaces/Client.md"}'),n={name:"api/host/interfaces/Client.md"};function s(d,e,i,c,l,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<p><a href="./../../packages">@oona/vlo</a> / <a href="./../">host</a> / Client</p><h1 id="interface-client" tabindex="-1">Interface: Client <a class="header-anchor" href="#interface-client" aria-label="Permalink to &quot;Interface: Client&quot;">​</a></h1><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L101" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:101</a></p><p>The control-plane client. Every method maps to one <code>/v1</code> route and throws a plain <code>Error</code> carrying the status and body on a non-2xx answer. Names may be passed as the definition objects themselves (<code>activity(...)</code>, <code>signal(...)</code>, <code>defineWorkflow(...)</code>).</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="cancel" tabindex="-1">cancel() <a class="header-anchor" href="#cancel" aria-label="Permalink to &quot;cancel()&quot;">​</a></h3><blockquote><p><strong>cancel</strong>(<code>runId</code>): <code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L132" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:132</a></p><p>Cancels the run and returns its view.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="runid" tabindex="-1">runId <a class="header-anchor" href="#runid" aria-label="Permalink to &quot;runId&quot;">​</a></h5><p><code>string</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>&gt;</p><hr><h3 id="events" tabindex="-1">events() <a class="header-anchor" href="#events" aria-label="Permalink to &quot;events()&quot;">​</a></h3><blockquote><p><strong>events</strong>(<code>runId</code>, <code>since?</code>): <code>Promise</code>&lt;<a href="./Envelope"><code>Envelope</code></a>[]&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L128" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:128</a></p><p>Journaled events with <code>seq &gt; since</code> (default 0).</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="runid-1" tabindex="-1">runId <a class="header-anchor" href="#runid-1" aria-label="Permalink to &quot;runId&quot;">​</a></h5><p><code>string</code></p><h5 id="since" tabindex="-1">since? <a class="header-anchor" href="#since" aria-label="Permalink to &quot;since?&quot;">​</a></h5><p><code>number</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./Envelope"><code>Envelope</code></a>[]&gt;</p><hr><h3 id="find" tabindex="-1">find() <a class="header-anchor" href="#find" aria-label="Permalink to &quot;find()&quot;">​</a></h3><blockquote><p><strong>find</strong>(<code>runId</code>): <code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a> | <code>null</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L126" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:126</a></p><p>The run&#39;s current view, or <code>null</code> when the host has no such run.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="runid-2" tabindex="-1">runId <a class="header-anchor" href="#runid-2" aria-label="Permalink to &quot;runId&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a> | <code>null</code>&gt;</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to &quot;get()&quot;">​</a></h3><blockquote><p><strong>get</strong>(<code>runId</code>): <code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L124" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:124</a></p><p>The run&#39;s current view.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="runid-3" tabindex="-1">runId <a class="header-anchor" href="#runid-3" aria-label="Permalink to &quot;runId&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>&gt;</p><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to &quot;list()&quot;">​</a></h3><blockquote><p><strong>list</strong>(<code>query?</code>): <code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>[]&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L134" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:134</a></p><p>Runs in the host&#39;s namespace matching the query.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="query" tabindex="-1">query? <a class="header-anchor" href="#query" aria-label="Permalink to &quot;query?&quot;">​</a></h5><p><a href="./ListQuery"><code>ListQuery</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>[]&gt;</p><hr><h3 id="signal" tabindex="-1">signal() <a class="header-anchor" href="#signal" aria-label="Permalink to &quot;signal()&quot;">​</a></h3><blockquote><p><strong>signal</strong>(<code>runId</code>, <code>name</code>, <code>payload</code>): <code>Promise</code>&lt;<a href="./SignalResult"><code>SignalResult</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L105" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:105</a></p><p>Sends a signal; buffered when the run is not waiting for it yet.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="runid-4" tabindex="-1">runId <a class="header-anchor" href="#runid-4" aria-label="Permalink to &quot;runId&quot;">​</a></h5><p><code>string</code></p><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>string</code> | { <code>name</code>: <code>string</code>; }</p><h5 id="payload" tabindex="-1">payload <a class="header-anchor" href="#payload" aria-label="Permalink to &quot;payload&quot;">​</a></h5><p><a href="./../../index/type-aliases/Json"><code>Json</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./SignalResult"><code>SignalResult</code></a>&gt;</p><hr><h3 id="signallink" tabindex="-1">signalLink() <a class="header-anchor" href="#signallink" aria-label="Permalink to &quot;signalLink()&quot;">​</a></h3><blockquote><p><strong>signalLink</strong>(<code>runId</code>, <code>name</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./SignalLink"><code>SignalLink</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L111" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:111</a></p><p>Mints a URL that delivers this one signal to this one run without a bearer token — the thing you put in an email. The host signs it; opening it renders a confirmation form, and submitting that form is what signals the run.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="runid-5" tabindex="-1">runId <a class="header-anchor" href="#runid-5" aria-label="Permalink to &quot;runId&quot;">​</a></h5><p><code>string</code></p><h5 id="name-1" tabindex="-1">name <a class="header-anchor" href="#name-1" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>string</code> | { <code>name</code>: <code>string</code>; }</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to &quot;options?&quot;">​</a></h5><p><a href="./SignalLinkOptions"><code>SignalLinkOptions</code></a></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./SignalLink"><code>SignalLink</code></a>&gt;</p><hr><h3 id="start" tabindex="-1">start() <a class="header-anchor" href="#start" aria-label="Permalink to &quot;start()&quot;">​</a></h3><blockquote><p><strong>start</strong>(<code>workflow</code>, <code>input</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L103" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:103</a></p><p>Starts a run and returns its view once the row exists (status <code>created</code> or later).</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="workflow" tabindex="-1">workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;workflow&quot;">​</a></h5><p><code>string</code> | { <code>name</code>: <code>string</code>; }</p><h5 id="input" tabindex="-1">input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;input&quot;">​</a></h5><p><a href="./../../index/type-aliases/Json"><code>Json</code></a></p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;options?&quot;">​</a></h5><p><a href="./StartOptions"><code>StartOptions</code></a></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>&gt;</p><hr><h3 id="startfresh" tabindex="-1">startFresh() <a class="header-anchor" href="#startfresh" aria-label="Permalink to &quot;startFresh()&quot;">​</a></h3><blockquote><p><strong>startFresh</strong>(<code>workflow</code>, <code>input</code>, <code>options</code>): <code>Promise</code>&lt;<a href="./StartFreshResult"><code>StartFreshResult</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L122" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:122</a></p><p>Starts a run under <code>runId</code>, or under <code>${runId}_2</code>, <code>_3</code>, … once earlier runs with the key have ended: the first id with no run is started, a live one is joined. The walk is deterministic, so two concurrent callers land on the same id and the insert&#39;s <code>ON CONFLICT DO NOTHING</code> makes one of them the joiner.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="workflow-1" tabindex="-1">workflow <a class="header-anchor" href="#workflow-1" aria-label="Permalink to &quot;workflow&quot;">​</a></h5><p><code>string</code> | { <code>name</code>: <code>string</code>; }</p><h5 id="input-1" tabindex="-1">input <a class="header-anchor" href="#input-1" aria-label="Permalink to &quot;input&quot;">​</a></h5><p><a href="./../../index/type-aliases/Json"><code>Json</code></a></p><h5 id="options-2" tabindex="-1">options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;options&quot;">​</a></h5><p><a href="./StartFreshOptions"><code>StartFreshOptions</code></a></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./StartFreshResult"><code>StartFreshResult</code></a>&gt;</p><hr><h3 id="stream" tabindex="-1">stream() <a class="header-anchor" href="#stream" aria-label="Permalink to &quot;stream()&quot;">​</a></h3><blockquote><p><strong>stream</strong>(<code>runId</code>, <code>options?</code>): <code>AsyncIterable</code>&lt;<a href="./../type-aliases/StreamMessage"><code>StreamMessage</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L130" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:130</a></p><p>Live events over SSE: journal envelopes, <code>cmd.emit</code> payloads, then one <code>end</code>.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="runid-6" tabindex="-1">runId <a class="header-anchor" href="#runid-6" aria-label="Permalink to &quot;runId&quot;">​</a></h5><p><code>string</code></p><h5 id="options-3" tabindex="-1">options? <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;options?&quot;">​</a></h5><p><a href="./StreamOptions"><code>StreamOptions</code></a></p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>AsyncIterable</code>&lt;<a href="./../type-aliases/StreamMessage"><code>StreamMessage</code></a>&gt;</p><hr><h3 id="waitfor" tabindex="-1">waitFor() <a class="header-anchor" href="#waitfor" aria-label="Permalink to &quot;waitFor()&quot;">​</a></h3><blockquote><p><strong>waitFor</strong>(<code>runId</code>, <code>status</code>, <code>timeoutMs?</code>): <code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/client/index.ts#L136" target="_blank" rel="noreferrer">sdk/ts/sdk/src/client/index.ts:136</a></p><p>Polls every 50 ms until the run reaches one of <code>status</code>. Throws after <code>timeoutMs</code> (default 10 s).</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="runid-7" tabindex="-1">runId <a class="header-anchor" href="#runid-7" aria-label="Permalink to &quot;runId&quot;">​</a></h5><p><code>string</code></p><h5 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;status&quot;">​</a></h5><p><a href="./../../index/type-aliases/RunStatus"><code>RunStatus</code></a> | readonly <a href="./../../index/type-aliases/RunStatus"><code>RunStatus</code></a>[]</p><h5 id="timeoutms" tabindex="-1">timeoutMs? <a class="header-anchor" href="#timeoutms" aria-label="Permalink to &quot;timeoutMs?&quot;">​</a></h5><p><code>number</code></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./RunView"><code>RunView</code></a>&gt;</p>',138)])])}const b=a(n,[["render",s]]);export{p as __pageData,b as default};
